// Title: Compare HTML output of an Excel workbook before and after attempting redundant space removal with Aspose.Cells for .NET
// Common Searches: how to detect redundant spaces in HTML generated by Aspose.Cells C# | compare two HTML strings saved from the same workbook using Aspose.Cells | Aspose.Cells HTML export default vs trimmed output C# example | check if Aspose.Cells HtmlSaveOptions can remove extra whitespace | C# code to compare Excel to HTML conversion results
// Tags: Aspose.Cells HtmlSaveOptions whitespace handling | C# string equality for Aspose.Cells HTML output | Excel to HTML conversion redundancy check | Aspose.Cells HTML export configuration options | detect HTML output differences Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;

// The sample loads an Excel workbook, saves it to HTML twice using Aspose.Cells' HtmlSaveOptions (both with default settings because a redundant‑space property is not available), reads the HTML from memory streams, compares the two strings for exact equality, and writes the comparison result and each HTML length to the console while handling missing files and runtime exceptions.
class HtmlRedundantSpaceComparison
{
    static void Main()
    {
        try
        {
            const string inputPath = "input.xlsx";

            // Verify that the input workbook exists to avoid FileNotFoundException
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Error: The file \"{inputPath}\" was not found.");
                return;
            }

            // Load the source workbook
            Workbook workbook = new Workbook(inputPath);

            // Save the workbook to HTML with default settings (redundant spaces not deleted)
            string htmlDefault;
            using (MemoryStream msDefault = new MemoryStream())
            {
                HtmlSaveOptions defaultOptions = new HtmlSaveOptions();
                workbook.Save(msDefault, defaultOptions);
                msDefault.Position = 0;
                using (StreamReader reader = new StreamReader(msDefault))
                {
                    htmlDefault = reader.ReadToEnd();
                }
            }

            // Save the workbook to HTML with trimmed settings.
            // Note: The ExportRedundantSpaces property is not available in the current Aspose.Cells version,
            // so we use the default options for the trimmed version as well.
            string htmlTrimmed;
            using (MemoryStream msTrimmed = new MemoryStream())
            {
                HtmlSaveOptions trimmedOptions = new HtmlSaveOptions();
                // If a future version provides a property to control redundant spaces,
                // it can be set here.
                workbook.Save(msTrimmed, trimmedOptions);
                msTrimmed.Position = 0;
                using (StreamReader reader = new StreamReader(msTrimmed))
                {
                    htmlTrimmed = reader.ReadToEnd();
                }
            }

            // Compare the two HTML outputs
            bool areEqual = string.Equals(htmlDefault, htmlTrimmed, StringComparison.Ordinal);
            Console.WriteLine("Are the HTML files identical? " + (areEqual ? "Yes" : "No"));

            // If they differ, optionally output the differences length
            if (!areEqual)
            {
                Console.WriteLine("Length of default HTML: " + htmlDefault.Length);
                Console.WriteLine("Length of trimmed HTML: " + htmlTrimmed.Length);
            }
        }
        catch (Exception ex)
        {
            // Catch any unexpected exceptions and display a friendly message
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }
}
